'use strict';
(async()=>{
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const params=new URLSearchParams(location.search);let tab=params.get('tab')||'assets',page=0,filtered=[],assets=[],maps=[],records=[],media={},related=params.get('related');const size=36;
const image=a=>a.image?`<img loading="lazy" src="data/visual/${esc(a.image)}" alt="${esc(a.displayName||a.name)}">`:'<div class="placeholder">Preview unavailable</div>';
const recordURL=r=>r.table==='heroes'&&r.profileId?`characters.html?id=${r.profileId}`:`index.html?record=${encodeURIComponent(r.id)}&table=${encodeURIComponent(r.table)}#${encodeURIComponent(r.table)}`;
const tabs=['assets','heroes','monsters','npcs','items','maps'];
const source=t=>t==='maps'?maps:t==='assets'?assets:records.filter(r=>r.table===({heroes:'heroes',monsters:'monsters',npcs:'npcs',items:'static-items'}[t]));
function matches(r,t){const q=$('#query').value.toLowerCase().trim(),cat=$('#category').value,status=$('#status').value,names=[r.name,r.displayName,...r.aliases||[]];const text=($('#search-scope').value==='name'?names:[...names,r.bundle,...r.tilesets||[]]).join(' ').toLowerCase();return (!q||text.includes(q))&&(!cat||t!=='assets'||r.category===cat)&&(!status||(r.status||(r.image?'ready':'unavailable'))===status)}
function apply(fallback=false){page=0;$('#fallback-note').textContent='';
 if(related){const ids=new Set(media[related]?.assetIds||[]);filtered=assets.filter(a=>ids.has(a.id));tab='assets';$('#fallback-note').textContent='Artwork linked directly to the selected record. Edit the search to explore other names.';
 if(!filtered.length){const [table,id]=related.split(':');filtered=records.filter(r=>r.table===table&&String(r.id)===id);tab=({heroes:'heroes',monsters:'monsters',npcs:'npcs','static-items':'items'}[table])||'assets';}}
 else{filtered=source(tab).filter(r=>matches(r,tab));if(fallback&&!filtered.length&&$('#query').value.trim()){for(const t of tabs.filter(t=>t!==tab)){const found=source(t).filter(r=>matches(r,t));if(found.length){tab=t;filtered=found;$('#fallback-note').textContent='No matches in the requested section. Showing the first section with results.';break}}}}
 document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));$('#category').hidden=tab!=='assets';const p=new URLSearchParams({tab,q:$('#query').value,scope:$('#search-scope').value,category:$('#category').value,status:$('#status').value,page});if(related)p.set('related',related);history.replaceState(null,'','?'+p);
 $('#summary').textContent=`${filtered.length.toLocaleString()} matching ${tab==='maps'?'maps':tab==='assets'?'graphics':'records'}`;render();}
function render(){const state=new URLSearchParams(location.search);state.set('page',page);history.replaceState(null,'','?'+state);const slice=filtered.slice(page*size,(page+1)*size);$('#grid').innerHTML=slice.map(r=>tab==='maps'?`<a class="card" href="${r.status==='ready'?'map-preview.html?map='+encodeURIComponent(r.name):'#'}" ${r.status==='ready'?'':`data-unavailable="${esc(r.name)}"`}>${r.image?image(r):'<div class="placeholder">Unsupported / unavailable</div>'}<div class="info"><strong>${esc(r.name)}</strong><small>${r.status==='ready'?`${r.tiles.toLocaleString()} tiles · ${r.layers} layers · ${Math.round(100*r.artworkTiles/Math.max(1,r.tiles))}% static artwork`:esc(r.error)}</small></div></a>`:tab==='assets'?`<button class="card" data-asset="${r.id}">${image(r)}<span class="info"><strong>${esc(r.name||r.type)}</strong><small class="alias">${esc((r.aliases||[]).join(' · '))}</small><small>${esc(r.presentation||r.type)} · ${r.width||'?'} × ${r.height||'?'}</small><small>${esc(r.bundle.split('/Android/').pop())}</small></span></button>`:`<a class="card" href="${recordURL(r)}">${image(r)}<div class="info"><strong>${esc(r.displayName||r.name)}</strong>${r.displayName?`<small class="alias">${esc(r.name)}</small>`:''}<small>#${r.id} · ${esc(r.presentation)}</small></div></a>`).join('')||'<p>No matches. Try another name or clear the filters.</p>';$('#prev').disabled=page===0;$('#next').disabled=(page+1)*size>=filtered.length;$('#page').textContent=`${filtered.length?page+1:0} / ${Math.ceil(filtered.length/size)}`}
function switchTab(t){related=null;tab=tabs.includes(t)?t:'assets';apply()}
function saveAssetJSON(a){const u=URL.createObjectURL(new Blob([JSON.stringify(a,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=u;link.download=(a.name||a.id)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
try{const load=async name=>{const r=await fetch('data/visual/'+name+'.json');if(!r.ok)throw Error(name+' catalog unavailable');return r.json()};[assets,maps,records,media]=await Promise.all([load('assets'),load('maps'),load('records'),load('record-media')]);$('#query').value=params.get('q')||'';$('#search-scope').value=params.get('scope')==='name'?'name':'all';$('#category').value=params.get('category')||'';$('#status').value=params.get('status')||'';if(!tabs.includes(tab))tab='assets';apply(true);page=Math.max(0,Math.min(Number(params.get('page'))||0,Math.ceil(filtered.length/size)-1));render();let timer;$('#query').oninput=()=>{clearTimeout(timer);related=null;timer=setTimeout(()=>apply(true),160)};$('#category').onchange=$('#status').onchange=$('#search-scope').onchange=()=>{related=null;apply(true)};document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('#prev').onclick=()=>{page--;render()};$('#next').onclick=()=>{page++;render()};$('#grid').onclick=e=>{if(e.target.closest('[data-unavailable]')){e.preventDefault();return}const b=e.target.closest('[data-asset]');if(!b)return;const a=assets.find(a=>a.id===b.dataset.asset);$('#detail-body').innerHTML=`<h2>${esc(a.name||a.type)}</h2>${image(a)}<p>${esc(a.presentation||a.type)} · original ${a.width||'?'} × ${a.height||'?'} px · ${esc(a.status)}</p><p>${esc(a.bundle)}</p>${a.error?`<p>Unresolved: ${esc(a.error)}</p>`:''}${a.image?`<a href="data/visual/${esc(a.image)}" download="${esc(a.name||a.id)}.webp">Download image preview</a>`:''}<div class="record-links"><button id="asset-json">Download asset metadata JSON</button><a href="files.html?q=${encodeURIComponent(a.bundle)}">Find original source file ↗</a></div><h3>Associated entries</h3><div class="record-links">${(a.records||[]).map(r=>`<a href="${recordURL(r)}">${esc(r.displayName||r.name)} · ${esc(r.table)} #${r.id}</a>`).join('')||'<p>No verified record association.</p>'}</div>`;$('#asset-json').onclick=()=>saveAssetJSON(a);$('#detail').showModal()};$('#close').onclick=()=>$('#detail').close()}catch(e){$('#summary').textContent='Unable to load the visual library: '+e.message}
})();
